            "name": "CommandPaletteItem",
            "subComponentOf": "CommandPalette",
            "displayName": "Command Palette Item",
            "isHiddenFromOverview": true,
            "description": "One option in a command palette result list. CommandPalette context supplies selection, highlight, identity, and close behavior.",
            "usage": {
              "description": "Use CommandPaletteItem for one non-interactive result row inside CommandPaletteList or CommandPaletteGroup. CommandPalette owns the composite keyboard model; standalone items expose only their explicit visual state and pointer activation.",
              "bestPractices": [
                {
                  "guidance": true,
                  "description": "Keep each value unique within the result list so highlight, active-descendant identity, and selection resolve to the same item."
                },
                {
                  "guidance": true,
                  "description": "Inside CommandPalette, each item is an option in the listbox popup of the WAI-ARIA combobox pattern: keyboard focus stays in the query field, arrow keys move the highlight through aria-activedescendant, and Enter selects the highlighted item."
                },
                {
                  "guidance": false,
                  "description": "Nest buttons, links, or other interactive controls inside an item. Option semantics make descendants presentational, so use non-interactive content such as icons, descriptions, and shortcut hints, and activate the option itself."
                },
                {
                  "guidance": false,
                  "description": "Treat isHighlighted as selection. Highlight is the active keyboard result; isSelected represents the chosen value."
                }
              ],
              "anatomy": [
                {
                  "name": "Item",
                  "required": true,
                  "description": "The option root that carries selection, disabled, item identity, interaction, and theme state."
                },
